const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.006, 40.7128]);
  const date1 = '2019-01-29';
  const date2 = '2019-02-05';

  // 2. Data Acquisition
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY');

  // Get images for both dates
  const col1 = era5.filterDate(date1, ee.Date(date1).advance(1, 'day'))
                    .filterBounds(nyc);

  const col2 = era5.filterDate(date2, ee.Date(date2).advance(1, 'day'))
                    .filterBounds(nyc);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Jan 29 images: ${size1}`);
  console.log(`Feb 5 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Missing data for one or both dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get mean temperature for each day
  const img1 = col1.mean().select('temperature_2m');
  const img2 = col2.mean().select('temperature_2m');

  // 4. Calculate temperatures in Celsius
  const temp1_k = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nyc,
    scale: 11132,
    maxPixels: 1e9
  }).get('temperature_2m');

  const temp2_k = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nyc,
    scale: 11132,
    maxPixels: 1e9
  }).get('temperature_2m');

  const temp1_k_val = temp1_k.getInfo();
  const temp2_k_val = temp2_k.getInfo();

  if (temp1_k_val === null || temp2_k_val === null) {
    console.log("Temperature calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert to Celsius
  const temp1_c = temp1_k_val - 273.15;
  const temp2_c = temp2_k_val - 273.15;
  const diff = Math.abs(temp2_c - temp1_c);

  // 5. Validation & Final Answer
  console.log(`Jan 29 temp: ${temp1_c.toFixed(2)}°C`);
  console.log(`Feb 5 temp: ${temp2_c.toFixed(2)}°C`);
  console.log(`Temperature difference: ${diff.toFixed(2)}°C`);

  if (diff >= 24) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
